<script setup lang="ts">
import {ref,watch} from 'vue'
import AdminImportDialog from './AdminImportDialog.vue'
import SiteDialog from '@/features/management-shared/SiteDialog.vue'
import {getAdminApi,type AdminRow} from './api'
import {getTeacherQuestionBankApi} from '@/features/teacher-question-banks/api'
import {getTeacherBankManagementApi} from '@/features/teacher-bank-management/api'
import {getTeacherStandaloneQuestionBankApi} from '@/features/teacher-bank-management/standalone-api'
const props=defineProps<{open:boolean;row?:AdminRow}>(),emit=defineEmits<{close:[];changed:[]}>(),admin=getAdminApi(),api=getTeacherQuestionBankApi(),manage=getTeacherBankManagementApi(),standalone=getTeacherStandaloneQuestionBankApi()
const courses=ref<AdminRow[]>([]),form=ref({name:'',description:'',visibility:'private',course_id:0}),busy=ref(false),error=ref(''),mode=ref('edit'),target=ref(0),importOpen=ref(false)
watch(()=>props.open,async(open)=>{if(!open)return;mode.value='edit';error.value='';form.value={name:props.row?.name||'',description:props.row?.description||'',visibility:props.row?.visibility||'private',course_id:props.row?.course_id||0};try{courses.value=(await admin.get<{items:AdminRow[]}>('courses/')).items}catch(e){error.value=(e as Error).message}})
async function run(action:()=>Promise<unknown>){busy.value=true;error.value='';try{await action();emit('changed');emit('close')}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function save(){await run(()=>props.row?admin.post(`resources/banks/${props.row.id}/update/`,form.value):form.value.course_id?api.createBank(form.value.course_id,form.value):standalone.createBank(form.value))}
async function copy(){const row=props.row!;await run(()=>row.course_id?manage.copySharedBank(target.value,row.course_id,Number(row.created_by_id||row.owner_id),Number(row.id)):standalone.copySharedBank(Number(row.id)))}
async function visibility(){const row=props.row!;await run(()=>row.course_id?(row.visibility==='archived'?manage.restoreBank(row.course_id,Number(row.id)):manage.archiveBank(row.course_id,Number(row.id))):standalone.updateVisibility(Number(row.id),row.visibility==='archived'?'private':'archived'))}
</script>
<template><SiteDialog :open="open&&!importOpen" :title="mode==='archive'?(row?.visibility==='archived'?'恢复为私有':'归档题库'):row?'编辑题库信息':'新建题库'" subtitle="所属课程创建后不可直接变更" @close="emit('close')"><form v-if="mode==='edit'" id="bank-edit" class="form-grid" @submit.prevent="save"><label class="field">题库名称<input v-model="form.name" required :disabled="row?.visibility==='archived'"></label><label class="field">所属课程<select v-model="form.course_id" :disabled="Boolean(row)"><option :value="0">独立题库</option><option v-for="c in courses" :key="c.id" :value="c.id">{{ c.name }}</option></select></label><label class="field">题库说明<textarea v-model="form.description" rows="3" :disabled="row?.visibility==='archived'" /></label><label class="field">可见性<select v-model="form.visibility" :disabled="row?.visibility==='archived'"><option value="private">私有</option><option value="shared">共享</option><option v-if="row?.visibility==='archived'" value="archived">已归档</option></select></label><div v-if="row" class="action-grid"><a class="management-action-link" :href="row.detail_url">题目与题组管理 →</a><button type="button" :disabled="row.visibility==='archived'" @click="importOpen=true">导入题目</button><button v-if="row.visibility==='shared'" type="button" @click="mode='copy'">复制共享题库</button><button type="button" @click="mode='archive'">{{ row.visibility==='archived'?'恢复为私有':'归档题库' }}</button></div></form><div v-else-if="mode==='copy'" class="form-grid"><label v-if="row?.course_id" class="field">目标课程<select v-model="target"><option :value="0" disabled>选择目标课程</option><option v-for="c in courses.filter(c=>c.id!==row?.course_id)" :key="c.id" :value="c.id">{{ c.name }}</option></select></label><p>复制生成独立题库，不改动来源。跨课程知识点映射按服务器规则重新校验，需在目标题库核对后使用。</p></div><p v-else>归档保留已有题目及历史实验快照。恢复后题库设为私有。</p><p v-if="error" role="alert" class="error-block">{{ error }}</p><template #footer><button @click="emit('close')">取消</button><button v-if="mode==='edit'" class="primary" form="bank-edit" type="submit" :disabled="busy||row?.visibility==='archived'">保存</button><button v-else-if="mode==='copy'" class="primary" :disabled="busy||(Boolean(row?.course_id)&&!target)" @click="copy">确认复制</button><button v-else class="primary" :disabled="busy" @click="visibility">确认变更</button></template></SiteDialog><AdminImportDialog :row="importOpen?row:undefined" @close="importOpen=false" @changed="emit('changed')" /></template>
